def is_nested(string):
    def is_valid_nested_structure(s):
        stack = []
        for char in s:
            if char == '[':
                stack.append(char)
            elif char == ']':
                if not stack:
                    return False
                stack.pop()
        return not stack

    def count_nested_brackets(s):
        max_depth = 0
        current_depth = 0
        for char in s:
            if char == '[':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ']':
                current_depth -= 1
        return max_depth

    if not is_valid_nested_structure(string):
        return False

    return count_nested_brackets(string) > 1

# Example usage
print(is_nested('[[]]'))  # True
print(is_nested('[]]]]]]][[[[[]'))  # False
print(is_nested('[][]'))  # False
print(is_nested('[]'))  # False
print(is_nested('[[][]]'))  # True
print(is_nested('[[]][['))  # True

